css:
/* ============================================
   БАЗОВІ СТИЛІ
   ============================================ */

/* Фіксуємо Times New Roman для всієї форми */
.print-format,
.print-format * {
  font-family: "Times New Roman", Times, serif !important;
  line-height: 1.2;
}

.print-format{
    padding: 0mm;
}
.sheet {

  /* Кольорова схема за замовчуванням */
  --color-border: #cbd5e1;
  --color-border-qr: #e2e8f0;
  --color-bg: #ffffff;
  --color-text-primary: #0f172a;
  --color-text-secondary: #1e293b;
  --color-key: #475569;
  --color-shadow: rgba(0, 0, 0, 0.06);
  --color-shadow-qr: rgba(0, 0, 0, 0.08);
  --color-header-bg: #f8fafc;
  --color-accent: #3b82f6;

  display: grid;
  grid-template-columns: repeat(var(--cols), var(--label-w));
  grid-auto-rows: var(--label-h);
  gap: var(--gap);
  justify-content: start;
  align-content: start;
  padding: var(--page-margin-top) var(--page-margin-right) var(--page-margin-bottom) var(--page-margin-left);
  font-family: "Times New Roman", Times, serif;
  color: var(--color-text-secondary);
  font-size: var(--font);
  line-height: 1.2;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* ============================================
   МОНОХРОМНИЙ РЕЖИМ
   ============================================ */

.sheet-mono {
  --color-border: #000000;
  --color-border-qr: #333333;
  --color-bg: #ffffff;
  --color-text-primary: #000000;
  --color-text-secondary: #000000;
  --color-key: #000000;
  --color-shadow: transparent;
  --color-shadow-qr: transparent;
  --color-header-bg: #f5f5f5;
  --color-accent: #000000;
}

.sheet-mono .lbl {
  border-width: 0.6mm;
}

.sheet-mono .lbl-header {
  background: var(--color-header-bg);
  border-bottom: 1px solid #000000;
}

/* ============================================
   ЕТИКЕТКА
   ============================================ */

.lbl {
  --bg-logo: none;
  --bg-opacity: 0.1;
  
  box-sizing: border-box;
  border: 0.5mm solid var(--color-border);
  border-radius: 2.5mm;
  padding: 2.5mm 3mm;
  background: var(--color-bg);
  position: relative;
  overflow: hidden;
  box-shadow: 0 0.5mm 1mm var(--color-shadow);

  break-inside: avoid;
  page-break-inside: avoid;
}

/* Фоновий логотип */
.lbl::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 80%;
  height: 80%;
  background-image: var(--bg-logo);
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  opacity: var(--bg-opacity);
  z-index: 0;
  pointer-events: none;
}

.lbl-empty {
  border-color: transparent;
  visibility: hidden;
  box-shadow: none;
}

.lbl-empty::before {
  display: none;
}

/* ============================================
   HEADER З НАЗВОЮ ОРГАНІЗАЦІЇ
   ============================================ */

.lbl-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2mm;
  padding: 0.5mm 1mm;
  margin: -2.5mm -3mm 2mm -3mm;
  background: var(--color-header-bg);
  border-bottom: 0.3mm solid var(--color-border);
  position: relative;
  z-index: 1;
}

.lbl-org-name {
  font-weight: 700;
  font-size: calc(var(--font) - 1px);
  color: var(--color-text-primary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  text-align: center;
}

/* ============================================
   QR-КОД (абсолютне позиціонування)
   ============================================ */

.lbl-qr {
  position: absolute;
  top: 2mm;
  right: 2mm;
  width: var(--qr);
  height: var(--qr);
  border: 0.4mm solid var(--color-border-qr);
  border-radius: 1.5mm;
  padding: 1mm;
  background: var(--color-bg);
  box-shadow: 0 0.3mm 0.6mm var(--color-shadow-qr);
  display: block;
  z-index: 10;
}

/* QR нижче header, якщо є брендування */
.lbl-qr-with-header {
  top: 13mm;
}

/* ============================================
   КОНТЕНТ (зліва від QR)
   ============================================ */

.lbl-content {
  margin-right: calc(var(--qr) + 3mm);
  display: flex;
  flex-direction: column;
  gap: 1mm;
  position: relative;
  z-index: 1;
}

.lbl-title {
  font-weight: 700;
  font-size: calc(var(--font) + 1px);
  line-height: 1;
  color: var(--color-text-primary);
  margin-bottom: 0.3mm;
  word-break: break-word;
  overflow-wrap: break-word;
  
  /* Обмеження до 2 рядків */
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-clamp: 2;
}

/* ============================================
   ПОЛЯ (компактне відображення)
   ============================================ */

.lbl-field {
  display: flex;
  gap: 1mm;
  align-items: baseline;
  font-size: calc(var(--font) - 0.5px);
  line-height: 1.4;
}

.lbl-key {
  font-weight: 700;
  color: var(--color-key);
  white-space: nowrap;
  flex-shrink: 0;
}

.lbl-val {
  color: var(--color-text-secondary);
  word-break: break-word;
  overflow-wrap: break-word;
}

/* Моноширинний шрифт для інвентарного та серійного номерів */
.lbl-field:first-of-type .lbl-val,
.lbl-field:nth-of-type(2) .lbl-val {
  font-family: "Liberation Mono", "DejaVu Sans Mono", Consolas, monospace;
  font-weight: 700;
  color: var(--color-accent);
}

/* ============================================
   ДРУК
   ============================================ */

@media print {
  @page {
    size: A4;
    margin: 0;
  }
  
  .sheet {
    margin: 0;

  }

  .lbl {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  /* Забезпечуємо правильне відображення кольорів при друку */
  * {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
    color-adjust: exact !important;
  }
}

/* Монохромний режим - ще більший контраст при друку */
@media print {
  .sheet-mono .lbl {
    border-width: 0.7mm;
  }

  .sheet-mono .lbl-key {
    font-weight: 900;
  }
  
  .sheet-mono .lbl-field:first-of-type .lbl-val,
  .sheet-mono .lbl-field:nth-of-type(2) .lbl-val {
    color: var(--color-text-primary);
  }
}

html:
{# ------- параметри ------- #}
{%- set cols = (doc.columns or 3) | int -%}
{%- set label_w = (doc.label_width_mm or 66) -%}
{%- set label_h = (doc.label_height_mm or 42) -%}
{%- set gap = (doc.label_gap_mm or 0) -%}
{%- set margin = (doc.page_margin_mm or 5) -%}
{%- set font_px = (doc.font_px or 11) -%}
{%- set qr_mm = (doc.qr_size_mm or 15) -%}
{%- set show_inv = (doc.show_inventory_no or 0) == 1 -%}
{%- set show_sn = (doc.show_serial_no or 0) == 1 -%}
{%- set show_mvo = (doc.show_mvo or 0) == 1 -%}
{%- set show_org = (doc.show_organization or 0) == 1 -%}
{%- set show_loc = (doc.show_location or 0) == 1 -%}
{%- set show_logo = (doc.show_logo or 0) == 1 -%}
{%- set logo_img = doc.logo_image or "" -%}
{%- set logo_opacity = (doc.logo_opacity or 10) | int -%}
{%- set org_brand_name = doc.organization_name or "" -%}
{%- set print_mode = doc.print_mode or "Color" -%}
{%- set is_mono = print_mode == "Monochrome" -%}

{# ------- макрос для одного ярлика ------- #}
{%- macro label_block(item) -%}
  {% set a = frappe.get_cached_doc("oiAsset", item.asset) %}
  {% set title = item.override_title or a.asset_name or a.name %}
  {% set inv = item.override_inventory_no or a.inventory_no %}
  {% set sn = item.override_serial_no or a.serial_no %}
  {% set url = frappe.utils.get_url_to_form("oiAsset", a.name) %}

  {# Отримуємо МВО, Організацію та Місцезнаходження #}
  {% set mvo_doc = frappe.get_cached_doc("oiEmployee", a.responsible_employee) if a.responsible_employee else None %}
  {% set mvo_name = mvo_doc.full_name if mvo_doc else "" %}
  
  {# Організація - отримуємо organization_name замість системного імені #}
  {% set org_doc = frappe.get_cached_doc("oiOrganization", a.current_owner) if a.current_owner else None %}
  {% set org_name = org_doc.abbreviation if org_doc.abbreviation else org_doc.organization_name %}
  
  {% set loc_doc = frappe.get_cached_doc("oiLocation", a.location) if a.location else None %}
  {% set loc_name = loc_doc.full_address if loc_doc else "" %}

  {# Визначаємо, що показувати в header #}
  {% set header_text = org_name if show_org else org_brand_name %}

  <div class="lbl {{ 'lbl-mono' if is_mono else '' }}" style="{% if show_logo and logo_img %}--bg-logo: url('{{ logo_img }}'); --bg-opacity: {{ logo_opacity / 100 }};{% endif %}">
    {# Header з назвою організації #}
    {% if header_text %}
    <div class="lbl-header">
      <div class="lbl-org-name">{{ header_text }}</div>
    </div>
    {% endif %}
    

    {# QR-код в правому верхньому куті #}
    {% if qr_mm|int > 0 %}
      {% set data_uri = frappe.call("orange_inventory.print_utils.qr.png_data_uri", value=url, box_size=5, border=0) %}
      {% if data_uri %}<img src="{{ data_uri }}" alt="QR" class="lbl-qr {{ 'lbl-qr-with-header' if header_text else '' }}"/>{% endif %}
    {% endif %}

    {# Весь контент зліва #}
    <div class="lbl-content">
      <div class="lbl-title" title="{{ title }}">{{ title }}</div>
      
      {% if show_inv %}
      <div class="lbl-field"><span class="lbl-key">Інв. №:</span> <span class="lbl-val">{{ inv or "—" }}</span></div>
      {% endif %}
      
      {% if show_sn %}
      <div class="lbl-field"><span class="lbl-key">Сер. №:</span> <span class="lbl-val">{{ sn or "—" }}</span></div>
      {% endif %}
      
      {% if show_mvo and mvo_name %}
      <div class="lbl-field"><span class="lbl-key">МВО:</span> <span class="lbl-val">{{ mvo_name }}</span></div>
      {% endif %}
      
      {% if show_loc and loc_name %}
      <div class="lbl-field"><span class="lbl-key">Місце:</span> <span class="lbl-val">{{ loc_name }}</span></div>
      {% endif %}
    </div>

  </div>
{%- endmacro -%}

{# ------- аркуш з етикетками ------- #}
<div class="sheet {{ 'sheet-mono' if is_mono else '' }}"
     style="
      --cols: {{ cols }};
      --label-w: {{ label_w }}mm;
      --label-h: {{ label_h }}mm;
      --gap: {{ gap }}mm;
      --page-margin-left: {{ margin }}mm;
      --page-margin-right: {{ margin }}mm;
      --page-margin-top: {{margin}}mm;
      --page-margin-bottom: {{margin}}mm;
      --qr: {{ qr_mm }}mm;
      --font: {{ font_px }}px;
     ">

  {%- set total = 0 -%}
  {%- for it in doc.items or [] -%}
    {%- set copies = (it.copies or 1) | int -%}
    {%- set total = total + copies -%}
    {%- for i in range(copies) -%}
      {{ label_block(it) }}
    {%- endfor -%}
  {%- endfor -%}

  {# якщо треба добити ряд до кратності колонок #}
  {%- if total and (total % cols) != 0 -%}
    {%- for i in range(cols - (total % cols)) -%}
      <div class="lbl lbl-empty"></div>
    {%- endfor -%}
  {%- endif -%}
</div>
